import { readFile, readdir, writeFile } from 'node:fs/promises';
import path from 'node:path';

/** Keep redistribution notices alongside the generated plugin bundle. */
export async function buildNotices() {
  const lock = JSON.parse(await readFile('package-lock.json', 'utf8'));
  const sections = [
    '# Third-party notices\n\nGenerated by `npm run build` from the locked production dependencies.\n',
  ];
  for (const [directory, entry] of Object.entries(lock.packages)) {
    if (!directory || entry.dev) continue;
    const filenames = await readdir(directory);
    const licenses = filenames.filter(name => /^(licen[cs]e|copying|notice)(\.|$)/i.test(name));
    const name = directory.slice(directory.lastIndexOf('node_modules/') + 'node_modules/'.length);
    sections.push(`## ${name} ${entry.version}\n\nLicense: ${entry.license ?? 'See notices below'}.\n`);
    for (const filename of licenses) {
      const text = await readFile(path.join(directory, filename), 'utf8');
      sections.push(`### ${filename}\n\n\`\`\`text\n${text.trim()}\n\`\`\`\n`);
    }
  }
  const redocNotices = await readFile('node_modules/redoc/bundles/redoc.standalone.js.LICENSE.txt', 'utf8');
  sections.push(`## Redoc standalone distribution notices\n\n\`\`\`text\n${redocNotices.trim()}\n\`\`\`\n`);
  await writeFile('THIRD_PARTY_NOTICES.md', sections.join('\n'));
}
